using Microsoft.EntityFrameworkCore;
using TuTuc.Data;
using TuTuc.Models;
namespace TuTuc.Services;
public class VerificationManager(AppDbContext db,PrivateDocumentStore documents,ILogger<VerificationManager> log) {
 public async Task<VerificationQueueVm> Queue(string? status){status=status is "Chờ xác minh" or "Cần bổ sung" or "Đã xác minh" or "Từ chối"?status:"Chờ xác minh";var dossiers=await db.VerificationDossiers.Where(x=>x.Status==status).OrderBy(x=>x.SubmittedAt).ToListAsync();var owners=dossiers.Select(x=>x.OwnerId).ToArray();var providers=await db.ProviderProfiles.Where(x=>owners.Contains(x.OwnerId)).ToDictionaryAsync(x=>x.OwnerId,x=>x.CompanyName);return new(){Dossiers=dossiers,Names=providers,Status=status};}
 public async Task<VerificationDetailsVm?> Details(int ownerId,int? dossierId,bool admin){var user=await db.Accounts.SingleOrDefaultAsync(x=>x.Id==ownerId&&x.Role=="Provider");if(user is null)return null;var history=await db.VerificationDossiers.Where(x=>x.OwnerId==ownerId).OrderByDescending(x=>x.Id).ToListAsync();var dossier=dossierId is int selected?history.SingleOrDefault(x=>x.Id==selected):history.FirstOrDefault();if(dossierId.HasValue&&dossier is null)return null;var ids=history.Select(x=>x.Id).ToArray();var decisions=await db.VerificationDecisions.Where(x=>ids.Contains(x.DossierId)).OrderBy(x=>x.CreatedAt).ThenBy(x=>x.Sequence).ToListAsync();var admins=decisions.Select(x=>x.AdminId).Distinct().ToArray();return new(){Account=user,Provider=await db.ProviderProfiles.SingleOrDefaultAsync(x=>x.OwnerId==ownerId),Dossier=dossier,History=history,Decisions=decisions,Documents=await db.PrivateDocuments.Where(x=>x.OwnerId==ownerId&&x.Scope=="Verification"&&ids.Contains(x.ObjectId)).OrderBy(x=>x.Submission).ThenBy(x=>x.Id).ToListAsync(),AdminNames=await db.Accounts.Where(x=>admins.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.Name),Submission=new(){Content=dossier?.Content??"",Representative=dossier?.Representative??user.Name,Version=dossier is null?null:Convert.ToBase64String(dossier.Version)},Decision=new(){Id=dossier?.Id??0,Version=dossier is null?"":Convert.ToBase64String(dossier.Version),Outcome="Đã xác minh"},Submissions=await db.DossierSubmissions.Where(x=>ids.Contains(x.DossierId)).OrderBy(x=>x.Submission).ToListAsync(),IsAdmin=admin};}
 public async Task<VerificationDetailsVm?> AdminDetails(int dossierId){var dossier=await db.VerificationDossiers.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==dossierId);return dossier is null?null:await Details(dossier.OwnerId,dossierId,true);}
 public async Task<string> Decide(int adminId,VerificationDecisionInput input){if(!await db.Accounts.AnyAsync(x=>x.Id==adminId&&x.IsActive&&x.Role=="Admin"))return "Bạn không có quyền xác minh.";if(input.Outcome is not ("Đã xác minh" or "Cần bổ sung" or "Từ chối"))return "Quyết định không hợp lệ.";if(input.Outcome!="Đã xác minh"&&string.IsNullOrWhiteSpace(input.Reason))return "Cần nhập lý do khi từ chối hoặc yêu cầu bổ sung.";if((input.Reason??"").Length>500||(input.Comment??"").Length>500)return "Lý do và nhận xét tối đa 500 ký tự.";if(!AccountManager.TryVersion(input.Version,out var expected))return "Phiên bản hồ sơ không hợp lệ.";
 await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);try{var dossier=await db.VerificationDossiers.SingleOrDefaultAsync(x=>x.Id==input.Id);if(dossier is null)return "Không tìm thấy hồ sơ.";if(dossier.Status!="Chờ xác minh"||!dossier.Version.SequenceEqual(expected))return "Hồ sơ đã được xử lý hoặc vừa thay đổi. Hãy mở lại bản mới nhất.";var user=await db.Accounts.SingleAsync(x=>x.Id==dossier.OwnerId);if(!user.IsActive)return "Nhà cung cấp đã ngừng sử dụng tài khoản.";if(!await db.PrivateDocuments.AnyAsync(x=>x.Scope=="Verification"&&x.ObjectId==dossier.Id&&x.OwnerId==user.Id))return "Hồ sơ chưa có tài liệu xác minh; cần nhà cung cấp nộp đủ hồ sơ.";var sequence=(await db.VerificationDecisions.Where(x=>x.DossierId==dossier.Id).MaxAsync(x=>(int?)x.Sequence)??0)+1;db.VerificationDecisions.Add(new(){DossierId=dossier.Id,Sequence=sequence,AdminId=adminId,Outcome=input.Outcome,Reason=(input.Reason??"").Trim(),Comment=(input.Comment??"").Trim()});db.Entry(dossier).Property(x=>x.Version).OriginalValue=expected;dossier.Status=input.Outcome;user.VerificationStatus=input.Outcome;user.ProviderVerified=input.Outcome=="Đã xác minh";if(input.Outcome=="Đã xác minh"){user.ProviderStatus="Đang hoạt động";user.CurrentGovernanceDecisionId=null;}db.Notifications.Add(new(){OwnerId=user.Id,Title="Kết quả xác minh: "+input.Outcome,Description=(input.Reason??input.Comment??"Mở hồ sơ để xem kết quả."),Url="/Verification/Mine"});await db.SaveChangesAsync();await tx.CommitAsync();return "";}catch(DbUpdateConcurrencyException){await tx.RollbackAsync();return "Hồ sơ hoặc trạng thái nhà cung cấp vừa thay đổi. Hãy tải lại.";}catch(DbUpdateException e){await tx.RollbackAsync();log.LogError(e,"Không thể ghi quyết định xác minh.");return "Chưa thể lưu quyết định. Trạng thái cũ được giữ nguyên.";}}
 public async Task<string> Submit(int ownerId,VerificationSubmissionInput input){if(string.IsNullOrWhiteSpace(input.Content)||input.Content.Length>2000||string.IsNullOrWhiteSpace(input.Representative)||input.Representative.Length>100)return "Nội dung hồ sơ và người đứng tên bắt buộc; tối đa 2000 và 100 ký tự.";var user=await db.Accounts.SingleOrDefaultAsync(x=>x.Id==ownerId&&x.Role=="Provider"&&x.IsActive);if(user is null)return "Không tìm thấy nhà cung cấp đang hoạt động.";if(user.VerificationStatus is not ("Cần bổ sung" or "Từ chối" or "Đã thu hồi"))return "Hồ sơ hiện không ở trạng thái cần bổ sung hoặc nộp lại.";var upload=await documents.StageAsync(ownerId,"Verification",input.Files);if(upload.Error.Length>0)return upload.Error;await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);try{await db.Entry(user).ReloadAsync();if(!user.IsActive||user.VerificationStatus is not ("Cần bổ sung" or "Từ chối" or "Đã thu hồi")){documents.CleanupFiles(upload.Documents);return "Trạng thái nhà cung cấp vừa thay đổi. Hãy tải lại.";}VerificationDossier dossier;if(user.VerificationStatus=="Cần bổ sung"){dossier=await db.VerificationDossiers.Where(x=>x.OwnerId==ownerId).OrderByDescending(x=>x.Id).FirstAsync();if(dossier.Status!="Cần bổ sung"||!AccountManager.TryVersion(input.Version,out var expected)||!dossier.Version.SequenceEqual(expected)){documents.CleanupFiles(upload.Documents);return "Hồ sơ vừa thay đổi. Hãy tải lại trước khi bổ sung.";}db.Entry(dossier).Property(x=>x.Version).OriginalValue=expected;if(!await db.DossierSubmissions.AnyAsync(x=>x.DossierId==dossier.Id&&x.Submission==dossier.Submission))db.DossierSubmissions.Add(new DossierSubmission{DossierId=dossier.Id,Submission=dossier.Submission,Content=dossier.Content,Representative=dossier.Representative,SubmittedAt=dossier.SubmittedAt});dossier.Submission++;dossier.Content=input.Content.Trim();dossier.Representative=input.Representative.Trim();dossier.Status="Chờ xác minh";dossier.SubmittedAt=DateTime.UtcNow;}else{if(await db.VerificationDossiers.AnyAsync(x=>x.OwnerId==ownerId&&(x.Status=="Chờ xác minh"||x.Status=="Cần bổ sung"))){documents.CleanupFiles(upload.Documents);return "Đã có hồ sơ đang chờ xử lý.";}dossier=new(){OwnerId=ownerId,Content=input.Content.Trim(),Representative=input.Representative.Trim()};db.VerificationDossiers.Add(dossier);}user.VerificationStatus="Chờ xác minh";user.ProviderVerified=false;await db.SaveChangesAsync();db.DossierSubmissions.Add(new DossierSubmission{DossierId=dossier.Id,Submission=dossier.Submission,Content=dossier.Content,Representative=dossier.Representative,SubmittedAt=dossier.SubmittedAt});foreach(var d in upload.Documents){d.ObjectId=dossier.Id;d.Submission=dossier.Submission;}db.PrivateDocuments.AddRange(upload.Documents);foreach(var admin in await db.Accounts.Where(x=>x.Role=="Admin"&&x.IsActive).Select(x=>x.Id).ToListAsync())db.Notifications.Add(new(){OwnerId=admin,Title="Hồ sơ nhà cung cấp chờ xem xét",Description=$"Hồ sơ #{dossier.Id} vừa được gửi lại.",Url=$"/Verification/Details/{dossier.Id}"});await db.SaveChangesAsync();await tx.CommitAsync();return "";}catch(DbUpdateConcurrencyException){await tx.RollbackAsync();documents.CleanupFiles(upload.Documents);return "Hồ sơ hoặc trạng thái vừa thay đổi. Hãy tải lại.";}catch(DbUpdateException e){await tx.RollbackAsync();documents.CleanupFiles(upload.Documents);log.LogError(e,"Không thể gửi hồ sơ xác minh.");return "Chưa thể lưu hồ sơ. Dữ liệu trước đó được giữ nguyên.";}}
}


